<?php $categories=rows('SELECT * FROM official_job_categories ORDER BY name');$categoryEditing=!empty($_GET['category_id'])?row('SELECT * FROM official_job_categories WHERE id=?',[(int)$_GET['category_id']]):null; ?>
<section class="panel form-panel"><h2>Categorías de trabajador oficial</h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="official_job_category"><input type="hidden" name="category_id" value="<?=e($categoryEditing['id']??'')?>"><label>Nombre o número de categoría<input name="name" required maxlength="180" value="<?=e($categoryEditing['name']??'')?>"></label><button class="button secondary">Guardar categoría</button></form><ul class="plain-list"><?php foreach($categories as $category): ?><li><?=e($category['name'])?> <a href="/?page=jobs&category_id=<?=(int)$category['id']?>">Editar categoría</a></li><?php endforeach; ?></ul></section>
